import players

def solve(env):
    # dispatch to the per-level player for the current level, in a loop
    while not env.terminal():
        k = env.levels_completed + 1
        fn = getattr(players, f'play_level_{k}', None)
        if fn is None:
            return
        before = env.levels_completed
        fn(env)
        if env.levels_completed <= before:
            return  # no progress -> stop

def cell_symbol(color):
    """Classify one raw colour into the terrain alphabet."""
    color = int(color)
    if color in WALL_COLORS:
        return WALL
    if color in OPEN_COLORS:
        return OPEN
    if color in BLOCK_COLORS:
        return BLOCK
    if color in AVATAR_COLORS:
        return AVATAR
    return PRIZE


def band_grid(frame):
    """Quantise a frame onto the 6px band lattice as a symbolic grid."""
    return [[cell_symbol(frame[r][c]) for c in COL_ANCHORS] for r in ROW_ANCHORS]


